import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(msg);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [50, 1000, 500],
      [100, 1000, 1000],
      [0, 1000, 0],
      [33, 100, 33],
      [10, 999, 99], // floors: 999*10/100 = 99.9 → 99
    ])("%i%% of %i cents = %i cents", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 when subtotal is 0", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("floors down correctly for large subtotals", () => {
      const policy = new PercentageDiscountPolicy(7);
      // 123456 * 7 / 100 = 8641.92 → 8641
      expect(policy.computeDiscountCents(123456)).toBe(8641);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when subtotal is less than fixed amount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(300)).toBe(300);
    });

    it("returns 0 when subtotal is 0", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns subtotal when they are equal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects an empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against the original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 100
        new FixedAmountDiscountPolicy(200), // 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // 10% of 1000 = 100, + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 when subtotal is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("can exceed subtotal (Cart clamps later)", () => {
      const policies = [
        new FixedAmountDiscountPolicy(600),
        new FixedAmountDiscountPolicy(600),
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // each capped at 1000, sum = 2000 (Cart will clamp to 1000)
      expect(composite.computeDiscountCents(1000)).toBe(2000);
    });

    it("defaults to sum mode when not specified", () => {
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(50),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      // 10% of 1000 = 100, + 50 = 150
      expect(composite.computeDiscountCents(1000)).toBe(150);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to the remaining subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining = 900
        new PercentageDiscountPolicy(10), // 10% of 900 = 90, remaining = 810
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      const policiesA = [
        new FixedAmountDiscountPolicy(200), // takes 200, remaining = 800
        new PercentageDiscountPolicy(10), // 10% of 800 = 80
      ];
      const policiesB = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining = 900
        new FixedAmountDiscountPolicy(200), // takes 200, remaining = 700
      ];
      const compositeA = new CompositeDiscountPolicy(policiesA, "chain");
      const compositeB = new CompositeDiscountPolicy(policiesB, "chain");
      expect(compositeA.computeDiscountCents(1000)).toBe(280);
      expect(compositeB.computeDiscountCents(1000)).toBe(300);
    });

    it("stops when remaining reaches 0", () => {
      const policies = [
        new FixedAmountDiscountPolicy(1000), // takes all 1000
        new PercentageDiscountPolicy(50), // 50% of 0 = 0
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 when subtotal is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

