import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  quantity: number,
  weightGrams?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("always returns 0", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
    expect(calc.computeShippingCents([makeLine("a", 2, 500)], 5000)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([makeLine("a", 1)], 1000)).toBe(500);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 1)], 4999)).toBe(500);
    });

    it("returns flat fee when no freeOver is configured", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a", 3)], 100000)).toBe(799);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(calc.computeShippingCents([makeLine("a", 2)], 1000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 400)], 1000),
      ).toBe(300);
    });

    it("selects first bracket at boundary (weight == upToGrams)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 500)], 1000),
      ).toBe(300);
    });

    it("selects second bracket just above first boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 501)], 1000),
      ).toBe(700);
    });

    it("selects the last bracket at its boundary", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 5000)], 1000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(
        calc.computeShippingCents([makeLine("a", 1, 5001)], 1000),
      ).toBe(2000);
    });

    it("uses last bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      expect(
        calcNoOverflow.computeShippingCents([makeLine("a", 1, 5000)], 1000),
      ).toBe(900);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      expect(
        unsorted.computeShippingCents([makeLine("a", 1, 400)], 1000),
      ).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 2 items × 300g = 600g → second bracket
      expect(
        calc.computeShippingCents([makeLine("a", 2, 300)], 1000),
      ).toBe(700);
    });
  });
});

